package com.jinloes.prpilot.review;

import com.jinloes.prpilot.model.PRReviewRequest;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Generated protobuf code in a diff: the files protoc and its plugins write from .proto files.
 *
 * <p>A generated file whose .proto source, or any generator configuration, also changes in the diff
 * was regenerated, so {@link #plan} leaves it out of the reviewed diff: the .proto change says the
 * same thing in far fewer lines, and generated files are often a pull request's largest. A
 * generated file that changes alone stays in the diff and is listed as possibly edited by hand,
 * because the next regeneration silently discards such an edit.
 *
 * <p>Only the diff is read. A hand edit made in the same pull request as a regeneration is left out
 * along with it; a CI step that regenerates the code and compares it is the control for that.
 */
final class GeneratedProtoCode {

    /** Lines from the top of a file searched for a generator's header comment. */
    static final int HEADER_LINES = 10;

    /** Lines from the top of a file searched for the .proto file it was generated from. */
    static final int SOURCE_LINES = 40;

    /** Paths listed per group in the prompt section; the rest are counted. */
    static final int MAX_LISTED = 50;

    /**
     * File names protoc and the common protobuf and gRPC plugins generate. A name hand-written code
     * also uses, such as Connect's {@code _connect.ts}, is left to the header check.
     */
    private static final Pattern GENERATED_PATH =
            Pattern.compile(
                    "(?:\\.pb(?:\\.gw|\\.validate)?\\.go"
                            + "|_pb2(?:_grpc)?\\.pyi?"
                            + "|\\.pb\\.(?:h|cc)"
                            + "|_pb\\.(?:js|mjs|cjs|ts|d\\.ts|rb)"
                            + "|\\.pbobjc\\.[hm]"
                            + "|\\.(?:pb|grpc)\\.swift"
                            + "|\\.pb(?:enum|json|server|grpc)?\\.dart"
                            + "|[a-z0-9](?:OuterClass|OrBuilder|Grpc)\\.java"
                            + "|[a-z0-9]GrpcKt\\.kt"
                            + "|[a-z0-9]Grpc\\.cs)$");

    /**
     * Header comments generators write at the top of their output. The marker must open a comment,
     * so source code that merely quotes one in a string does not count.
     */
    private static final Pattern GENERATED_HEADER =
            Pattern.compile(
                    "^\\s*(?://+|#+|/\\*+|\\*+)\\s*(?:This file (?:is|was) )?"
                            + "(?:Generated by the protocol buffer compiler"
                            + "|Generated by the gRPC\\b"
                            + "|Generated by the Swift generator plugin for the protocol buffer"
                            + " compiler"
                            + "|Code generated by protoc-gen-"
                            + "|@generated by (?:protoc-gen-|prost-build)"
                            + "|@generated from file \\S+\\.proto"
                            + "|generated by rust-protobuf)",
                    Pattern.CASE_INSENSITIVE);

    /** The comment naming the .proto file a generated file comes from. */
    private static final Pattern SOURCE_LINE =
            Pattern.compile(
                    "^\\s*(?://+|#+|/?\\*+)\\s*(?:source:|@generated from file)\\s*(\\S+?\\.proto)\\b",
                    Pattern.CASE_INSENSITIVE);

    /**
     * Files that configure or run code generation, beyond the dependency manifests that pin the
     * generator and runtime versions.
     */
    private static final Pattern GENERATOR_CONFIG =
            Pattern.compile(
                    "(?i)(?:^|/)(?:buf(?:\\.work|\\.gen|\\.policy)?\\.ya?ml|buf\\.lock"
                            + "|(?:gnu)?makefile|[^/]*\\.mk|justfile|taskfile\\.ya?ml"
                            + "|build(?:\\.bazel)?|workspace(?:\\.bazel)?|module\\.bazel"
                            + "|[^/]*\\.bzl|tools\\.go)$");

    private static final Pattern DIFF_RECORD = Pattern.compile("\r?\n");

    private GeneratedProtoCode() {}

    /**
     * Which generated files to leave out of the reviewed diff and which to list as possibly edited
     * by hand. {@code diff} is the request's diff body.
     */
    record Plan(String diff, List<String> omitted, List<String> suspected) {
        Plan {
            omitted = List.copyOf(omitted);
            suspected = List.copyOf(suspected);
        }

        /** Whether the diff changes any generated file. */
        boolean found() {
            return !omitted.isEmpty() || !suspected.isEmpty();
        }

        /** Every generated file the diff changes, whether left out of the diff or kept. */
        Set<String> paths() {
            Set<String> paths = new LinkedHashSet<>(omitted);
            paths.addAll(suspected);
            return Set.copyOf(paths);
        }

        /**
         * The prompt section listing the generated files, or an empty string when there are none.
         */
        String section() {
            var text = new StringBuilder();
            appendGroup(
                    text,
                    "Left out of the diff because a .proto file or generator configuration they"
                            + " are generated from also changes:",
                    omitted);
            appendGroup(
                    text,
                    "Changed while no .proto file or generator configuration they are generated"
                            + " from changes, so possibly edited by hand:",
                    suspected);
            return text.toString();
        }

        /** The request with the omitted files removed from its diff and the files listed. */
        PRReviewRequest applyTo(PRReviewRequest request) {
            return found() ? request.withGeneratedCodeOmitted(diff, section()) : request;
        }

        private static void appendGroup(StringBuilder text, String heading, List<String> paths) {
            if (paths.isEmpty()) return;
            if (!text.isEmpty()) text.append('\n');
            text.append(heading).append('\n');
            paths.stream()
                    .limit(MAX_LISTED)
                    .forEach(path -> text.append("- ").append(path).append('\n'));
            if (paths.size() > MAX_LISTED) {
                text.append("- (and ").append(paths.size() - MAX_LISTED).append(" more)\n");
            }
        }
    }

    /**
     * Plans which generated files in {@code diff} to leave out. Every section other than an omitted
     * file's is kept verbatim and in order, as is any text before the first file.
     */
    static Plan plan(String diff) {
        List<String> sections = InspectionManifest.fileSections(diff);
        if (sections.isEmpty()) return new Plan(diff, List.of(), List.of());
        List<InspectionManifest.FileTarget> files = new ArrayList<>(sections.size());
        List<String> protos = new ArrayList<>();
        boolean configChanged = false;
        for (String section : sections) {
            InspectionManifest.FileTarget file = InspectionManifest.parseFile(section).orElse(null);
            files.add(file);
            if (file == null) continue;
            if (isProto(file.path())) protos.add(file.path());
            configChanged |= isGeneratorConfig(file.path());
        }
        int sectionChars = sections.stream().mapToInt(String::length).sum();
        var kept = new StringBuilder(diff.substring(0, diff.length() - sectionChars));
        List<String> omitted = new ArrayList<>();
        List<String> suspected = new ArrayList<>();
        for (int index = 0; index < sections.size(); index++) {
            InspectionManifest.FileTarget file = files.get(index);
            if (file != null && isGenerated(file)) {
                if (configChanged || fromChangedProto(file, protos)) {
                    omitted.add(file.path());
                    continue;
                }
                if (!isDeletion(file)) suspected.add(file.path());
            }
            kept.append(sections.get(index));
        }
        return new Plan(omitted.isEmpty() ? diff : kept.toString(), omitted, suspected);
    }

    /** Whether a changed file is protobuf code generated by protoc or one of its plugins. */
    static boolean isGenerated(InspectionManifest.FileTarget file) {
        if (isProto(file.path())) return false;
        if (GENERATED_PATH.matcher(file.path()).find()) return true;
        for (int line = 1; line <= HEADER_LINES; line++) {
            String text = file.newSideLines().get(line);
            if (text != null && GENERATED_HEADER.matcher(text).find()) return true;
        }
        return false;
    }

    /** The .proto file a generated file names as its source, when a visible line names one. */
    static Optional<String> sourceProto(InspectionManifest.FileTarget file) {
        for (int line = 1; line <= SOURCE_LINES; line++) {
            String text = file.newSideLines().get(line);
            if (text == null) continue;
            Optional<String> source = sourceProto(text);
            if (source.isPresent()) return source;
        }
        return Optional.empty();
    }

    /** The .proto file one line names as its source, when it is a generator's source comment. */
    static Optional<String> sourceProto(String line) {
        Matcher matcher = SOURCE_LINE.matcher(line);
        return matcher.find() ? Optional.of(matcher.group(1)) : Optional.empty();
    }

    /**
     * Whether a repository path and a generator's source name are the same .proto file. Generators
     * name the source relative to an import root, so either may be a suffix of the other.
     */
    static boolean sameProto(String path, String source) {
        String name = source.startsWith("./") ? source.substring(2) : source;
        return path.equals(name) || path.endsWith("/" + name) || name.endsWith("/" + path);
    }

    static boolean isGeneratorConfig(String path) {
        return GENERATOR_CONFIG.matcher(path).find()
                || TriggeredChecklists.DEPENDENCY_PATH.matcher(path).find();
    }

    private static boolean isProto(String path) {
        return path.toLowerCase(Locale.ROOT).endsWith(".proto");
    }

    /**
     * A generated file that names its source was regenerated when that source changed. One that
     * names none, or whose naming line is outside the diff's context, was when any .proto changed.
     */
    private static boolean fromChangedProto(
            InspectionManifest.FileTarget file, List<String> protos) {
        Optional<String> source = sourceProto(file);
        if (source.isEmpty()) return !protos.isEmpty();
        return protos.stream().anyMatch(path -> sameProto(path, source.get()));
    }

    private static boolean isDeletion(InspectionManifest.FileTarget file) {
        for (String line : DIFF_RECORD.split(file.diff())) {
            if (line.startsWith("@@")) return false;
            if (line.equals("+++ /dev/null") || line.startsWith("deleted file mode")) return true;
        }
        return false;
    }
}
